		talkContent_ph = 'Uy bata, may isang napakalakas na diyos-hayop sa unahan — mas mabuting huwag ka nang dumaan doon kung ayaw mong mapahamak.  ',
		talkContent_in = 'Anak kecil, di depan ada binatang legendaris yang sangat kuat, demi keselamatan lebih baik kamu jangan ke sana ya.',
		talkContent_vn = 'Nhóc con, phía trước có thần thú mạnh mẽ xuất hiện đấy, để an toàn thì tốt nhất là nhóc đừng nên đi qua đó nhé.'
	},
